module freq_divbyodd #(
    parameter NUM_DIV = 5
) (
    input clk,
    input rst_n,
    output reg clk_div
);

    reg [2:0] cnt1, cnt2;
    reg clk_div1, clk_div2;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            cnt1 <= 3'd0;
        end else begin
            cnt1 <= (cnt1 == (NUM_DIV - 1)) ? 3'd0 : cnt1 + 3'd1;
        end
    end

    always @(negedge clk or negedge rst_n) begin
        if (~rst_n) begin
            cnt2 <= 3'd0;
        end else begin
            cnt2 <= (cnt2 == (NUM_DIV - 1)) ? 3'd0 : cnt2 + 3'd1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            clk_div1 <= 1'b0;
        end else begin
            clk_div1 <= (cnt1 < (NUM_DIV / 2)) ? 1'b1 : 1'b0;
        end
    end

    always @(negedge clk or negedge rst_n) begin
        if (~rst_n) begin
            clk_div2 <= 1'b0;
        end else begin
            clk_div2 <= (cnt2 < (NUM_DIV / 2)) ? 1'b1 : 1'b0;
        end
    end

    always @(*) begin
        clk_div = clk_div1 | clk_div2;
    end

endmodule
